  qmPublishBody2: "ಪ್ರಕಟಿಸಿದರೆ ಮೆನು ನಮ್ಮಲ್ಲಿ ಉಳಿಯುತ್ತದೆ ಮತ್ತು QR ನಲ್ಲಿ ಅದರ ಬದಲಿಗೆ ಒಂದು ಸಣ್ಣ ಕೊಂಡಿ ಬರುತ್ತದೆ. ಮುದ್ರಿಸಿದ ಕೋಡ್ ಇನ್ನೆಂದೂ ಬದಲಾಗುವುದಿಲ್ಲ, ಗಾತ್ರದ ಮಿತಿಯೂ ಹೋಗುತ್ತದೆ. ಆಗ ನೋಡಲು ಗ್ರಾಹಕರಿಗೆ ಇಂಟರ್ನೆಟ್ ಬೇಕು, ಮತ್ತು ಕೊನೆಯ ಬಾರಿ ಸ್ಕ್ಯಾನ್ ಆದ 180 ದಿನಗಳ ನಂತರ ನಾವು ಮೆನುವನ್ನು ಅಳಿಸುತ್ತೇವೆ.",
