  qmOnlyThisBrowserBody: "ಇದು ನಿಮ್ಮದೇ ಎಂದು ಸಾಬೀತು ಮಾಡುವ ಕೀಲಿ ಇಲ್ಲೇ ಇದೆ, ಬೇರೆಲ್ಲೂ ಇಲ್ಲ. ಅದನ್ನು ಮರಳಿ ಪಡೆಯಲು ಯಾವ ಲಾಗಿನ್ ಇಲ್ಲ, ಹಾಗಾಗಿ ಈ ಬ್ರೌಸರಿನ ಮಾಹಿತಿ ಅಳಿಸುವುದು — ಅಥವಾ ಬೇರೆ ಫೋನ್ ಅಥವಾ ಗಣಕಕ್ಕೆ ಹೋಗುವುದು — ಎಂದರೆ ಮುದ್ರಿಸಿದ QR ಅನ್ನು ಇನ್ನೆಂದೂ ಬದಲಿಸಲು ಆಗುವುದಿಲ್ಲ. ಮೆನುವಿನ ಒಂದು ನಕಲು ಇಟ್ಟುಕೊಳ್ಳಲು ಪುಟದ ಮೇಲಿನಿಂದ ಅದನ್ನು ರಫ್ತು ಮಾಡಿಕೊಳ್ಳಿ.",
